<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\Relations\HasOne;

class Animal extends Model
{
    use HasFactory;

    public const STATUS_ACTIVE = 'active';
    public const STATUS_SOLD = 'sold';
    public const STATUS_DECEASED = 'deceased';
    public const STATUS_ARCHIVED = 'archived';

    // animal_code is deliberately NOT fillable. It is generated by the backend only.
    protected $fillable = [
        'animal_type_id',
        'name',
        'sex',
        'breed',
        'date_of_birth',
        'acquisition_type',
        'acquisition_date',
        'source',
        'weight_kg',
        'status',
        'notes',
        'created_by',
    ];

    protected $casts = [
        'date_of_birth' => 'date',
        'acquisition_date' => 'date',
        'weight_kg' => 'decimal:2',
    ];

    public function animalType(): BelongsTo
    {
        return $this->belongsTo(AnimalType::class);
    }

    public function healthRecords(): HasMany
    {
        return $this->hasMany(HealthRecord::class)->latest('observation_date');
    }

    public function feedingRecords(): HasMany
    {
        return $this->hasMany(FeedingRecord::class)->latest('fed_at');
    }

    public function purchaseItem(): HasOne
    {
        return $this->hasOne(PurchaseItem::class);
    }

    public function saleItem(): HasOne
    {
        return $this->hasOne(SaleItem::class);
    }

    public function createdBy(): BelongsTo
    {
        return $this->belongsTo(User::class, 'created_by');
    }

    public function isAvailableForSale(): bool
    {
        return $this->status === self::STATUS_ACTIVE;
    }

    /**
     * Allowed status changes:
     *  active   -> deceased, archived
     *  archived -> active
     *  sold and deceased are final and cannot be changed by editing.
     */
    public function canTransitionTo(string $status): bool
    {
        $allowed = match ($this->status) {
            self::STATUS_ACTIVE => [self::STATUS_ACTIVE, self::STATUS_DECEASED, self::STATUS_ARCHIVED],
            self::STATUS_ARCHIVED => [self::STATUS_ARCHIVED, self::STATUS_ACTIVE],
            default => [$this->status],
        };

        return in_array($status, $allowed, true);
    }

    /**
     * True when the animal has any health, feeding, purchase, or sale history.
     */
    public function hasRecords(): bool
    {
        return $this->healthRecords()->exists()
            || $this->feedingRecords()->exists()
            || $this->purchaseItem()->exists()
            || $this->saleItem()->exists();
    }
}
